<?php declare(strict_types=1); namespace Annam; $title='Store settings'; ?>
<form class="o-form" method="post" enctype="multipart/form-data"><?= csrf() ?><section class="o-card"><h2>Your store</h2><div class="o-grid-form"><?php foreach (['brand_name'=>'Store name','tagline'=>'Tagline','support_phone'=>'Contact phone'] as $key=>$label): ?><label class="o-field"><span><?= e($label) ?></span><input name="<?= e($key) ?>" value="<?= e($store->config[$key]) ?>"></label><?php endforeach; ?><label class="o-field"><span>Email</span><input type="email" name="contact_email" value="<?= e($store->config['theme']['contact_email']??'') ?>"></label><label class="o-field"><span>Logo</span><img src="<?= e($store->logo()) ?>" alt="Current logo" width="120"><input type="file" name="logo" accept="image/jpeg,image/png,image/webp"></label></div></section><button class="o-btn o-btn-primary" type="submit">Save settings</button></form>
